package cn.zhuatech.finagent.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class CloseReadinessService{public Result evaluate(Request r){double entity=r.closedEntities()*100.0/r.totalEntities();double recon=r.completedReconciliations()*100.0/r.requiredReconciliations();int score=(int)Math.round(entity*.4+recon*.4-Math.min(20,r.materialAdjustments()*5)-Math.min(20,r.pendingApprovals()*4)+20);score=Math.max(0,Math.min(100,score));List<String> actions=new ArrayList<>();if(entity<100)actions.add("完成剩余主体关账");if(recon<100)actions.add("清理未完成对账项目");if(r.materialAdjustments()>0)actions.add("复核重大调整分录及支持证据");if(r.pendingApprovals()>0)actions.add("催办关账审批");String status=r.daysToDeadline()<=1&&score<90||score<60?"BLOCK_CLOSE":score<90?"REMEDIATE":"READY";if(actions.isEmpty())actions.add("关账任务和复核证据已完备");return new Result(score,round(entity),round(recon),status,actions);}private double round(double v){return Math.round(v*10)/10.0;}
 public record Request(@Min(1) int totalEntities,@Min(0) int closedEntities,@Min(1) int requiredReconciliations,@Min(0) int completedReconciliations,@Min(0) int materialAdjustments,@Min(0) int pendingApprovals,@Min(0) int daysToDeadline){}public record Result(int readinessScore,double entityCloseRate,double reconciliationRate,String status,List<String> actions){} }
